DROP POLICY inspiration_votes_read ON public.inspiration_votes;
CREATE POLICY inspiration_votes_read ON public.inspiration_votes FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid() OR (c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE)) AND (voter_id=auth.uid() OR (c.votes_revealed_at IS NOT NULL AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE))));
DROP POLICY inspiration_votes_update ON public.inspiration_votes;
CREATE POLICY inspiration_votes_update ON public.inspiration_votes FOR UPDATE TO authenticated USING (voter_id=auth.uid() AND EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND c.votes_revealed_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()))) WITH CHECK (voter_id=auth.uid() AND EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=card_id AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND c.votes_revealed_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (choice='love' OR (c.mode='challenge' AND c.partner_id IS NOT NULL AND auth.uid() NOT IN (c.creator_id,c.partner_id)))));
DROP POLICY inspiration_votes_delete ON public.inspiration_votes;
DROP POLICY inspiration_delete ON public.cultural_inspirations;
CREATE POLICY inspiration_delete ON public.cultural_inspirations FOR DELETE TO authenticated USING (creator_id=auth.uid() AND trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()));
CREATE OR REPLACE FUNCTION trip_private.inspiration_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.trip_id<>OLD.trip_id OR NEW.creator_id<>OLD.creator_id OR NEW.partner_id IS DISTINCT FROM OLD.partner_id OR NEW.hidden_at IS DISTINCT FROM OLD.hidden_at OR NEW.votes_revealed_at IS DISTINCT FROM OLD.votes_revealed_at OR NEW.mode<>OLD.mode THEN RAISE EXCEPTION 'Experience ownership cannot be changed'; END IF; END IF; IF NEW.partner_id IS NOT NULL AND NOT trip_private.is_trip_member(NEW.trip_id,NEW.partner_id) THEN RAISE EXCEPTION 'Partner must be in the squad'; END IF; IF NEW.photo_path IS NOT NULL AND (split_part(NEW.photo_path,'/',1)<>NEW.id::text OR NEW.photo_path !~* '\.(jpe?g|png|webp)$') THEN RAISE EXCEPTION 'Invalid photo path'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;